"""Render the wallpaper collection, preserving the shared site shell and viewer."""
import json,re,html,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
def build():
 items=json.loads((ROOT/'data/wallpapers-studio.json').read_text())['items'];e=lambda s:html.escape(str(s),quote=True)
 cards=[]
 for i,item in enumerate(items):
  attrs=item['attrs'];downloads=''.join(f'<a class="ws-download" href="{e(l["url"])}" download="supercharged-{e(item["id"])}-{l["kind"]}.jpg"><span>{l["kind"].title()} ↗</span><small>{l["width"]} × {l["height"]}</small></a>' for l in item['links'])
  data=' '.join(f'{k}="{e(v)}"' for k,v in attrs.items() if k.startswith('data-'))
  cards.append(f'''<figure class="ws-card" data-id="{e(item['id'])}" data-category="{item['category']}" data-search="{e(item['title']+' '+re.sub('<[^>]+>',' ',item['description']))}">
  <div class="ws-card-image"><button class="ws-open" type="button" data-wp-open {data} data-wp-caption="{e(item['description'])}" aria-label="Preview {e(item['title'])}"><img src="{e(item['thumb'])}" data-phone-src="{e(item['thumb'])}" data-desktop-src="/assets/wallpapers/thumbs-desktop/{e(item['id'])}.webp" alt="{e(item['alt'])}" width="480" height="1040" loading="lazy" decoding="async" /></button><span class="ws-art-label">{'AI artwork' if item['ai'] else item['category']}</span><button class="ws-save ws-js" type="button" data-save="{e(item['id'])}" aria-label="Save {e(item['title'])}" aria-pressed="false">♡</button></div>
  <figcaption><div class="ws-card-heading"><span class="ws-index">{i+1:02}</span><h3>{e(item['title'])}</h3></div><p>{item['description']}</p><div class="ws-downloads">{downloads}</div></figcaption></figure>''')
 main='''<main id="main" class="ws-studio" data-format="phone">
 <section class="ws-hero" aria-labelledby="ws-title"><div class="ws-hero-copy"><p class="ws-eyebrow"><span></span> THE SUPERCHARGED WALLPAPER COLLECTION</p><h1 id="ws-title">Extraordinary.<br><em>Every time you<br>pick it up.</em></h1><p class="ws-intro">A launch. A late-night drive. A little electric energy. Give your everyday screen a different kind of view.</p><a class="ws-cta" href="#collection">Find your next wallpaper <span>↘</span></a><div class="ws-hero-facts"><span><b>16</b> distinct designs</span><span><b>4K</b> desktop editions</span><span><b>Free</b> personal downloads</span></div></div><div class="ws-hero-art"><div class="ws-halo"></div><div class="ws-desktop-frame"><div class="ws-frame-bar"><i></i><i></i><i></i><span>THE VIEW FROM HERE</span></div><img src="/assets/wallpapers/previews/ai-golden-hour-starship.webp" alt="Golden Hour Starship AI artwork in a desktop preview" width="1280" height="720" fetchpriority="high"/><div class="ws-frame-caption">01 / GOLDEN HOUR STARSHIP <span>AI ARTWORK</span></div></div><div class="ws-phone-frame"><img src="/assets/wallpapers/previews/ai-neon-city-cybertruck-phone.webp" alt="Neon City AI artwork in a phone preview" width="480" height="1040"/><span class="ws-phone-clock" aria-hidden="true">09:41</span><span class="ws-phone-pill" aria-hidden="true"></span></div><p class="ws-art-note">Two screens. One unmistakable point of view.</p></div></section>
 <section class="ws-collection" id="collection" aria-labelledby="ws-collection-title"><header class="ws-section-head"><div><p class="ws-eyebrow">THE GALLERY / 001—016</p><h2 id="ws-collection-title">Make it yours.</h2></div><p>Choose a view. Open it up. Download the full-resolution original.</p></header>
 <div class="ws-toolbar ws-js"><div class="ws-filters" role="group" aria-label="Wallpaper collection">'''+''.join(f'<button type="button" data-filter="{x}" aria-pressed="{str(x=="All").lower()}">{x}</button>' for x in ['All','SpaceX','Tesla','Signature','Saved'])+'''</div><div class="ws-format" role="group" aria-label="Preview format"><button type="button" data-format-choice="phone" aria-pressed="true">Phone</button><button type="button" data-format-choice="desktop" aria-pressed="false">Desktop</button></div><label class="ws-search"><span class="visually-hidden">Search wallpapers</span><input id="ws-search" type="search" placeholder="Find your next view…" autocomplete="off"/></label></div>
 <div class="ws-gallery-meta"><p id="ws-count" role="status">16 wallpapers · Phone and desktop editions</p><p id="ws-storage">Full-resolution files. No account needed.</p></div><div class="ws-grid" data-wp-gallery>'''+''.join(cards)+'''</div><div class="ws-empty" hidden><h3>A different view awaits.</h3><p id="ws-empty-copy">Try another search or collection.</p><button type="button" id="ws-reset">Show every wallpaper ↗</button></div></section>
 <section class="ws-guide" aria-labelledby="ws-guide-title"><div><p class="ws-eyebrow">FROM THE GALLERY TO YOUR SCREEN</p><h2 id="ws-guide-title">Three steps.<br>A fresh perspective.</h2><p>All designs are free for personal backgrounds. No signup, no email gate.</p></div><ol><li><span>01</span><div><h3>Find your favourite.</h3><p>Browse the collection and open a larger preview. Save a shortlist on this device.</p></div></li><li><span>02</span><div><h3>Pick your screen.</h3><p>Choose Phone for a portrait image or Desktop for a landscape original. Exact dimensions appear on every download.</p></div></li><li><span>03</span><div><h3>Make it your daily view.</h3><p>Save the image, then set it as your wallpaper in your device settings. On iPhone, open the downloaded image and use Share → Save Image first.</p></div></li></ol></section>
 <section class="ws-license"><h2>Made to be seen.</h2><p>Free for personal use as phone and desktop backgrounds. Please don’t resell them. Original artwork made for Supercharged Daily, except the Falcon 9 launch photos, which are public-domain NASA images credited to their photographers. AI artwork is labelled. Not affiliated with Tesla, SpaceX, NASA or xAI.</p><a href="/news.html#newsletter">A fresh perspective, every Sunday. Get the newsletter →</a></section></main>'''
 p=ROOT/'wallpapers.html';s=p.read_text();s=re.sub(r'<main\b[\s\S]*?</main>',lambda _:main,s,count=1)
 if 'wallpapers-studio.css' not in s:s=s.replace('</head>','    <link rel="stylesheet" href="/wallpapers-studio.css?v=20261026"/>\n  </head>',1)
 if 'wallpapers-studio.js' not in s:s=s.replace('</body>','    <script defer src="/wallpapers-studio.js?v=20261026"></script>\n  </body>')
 s=s.replace('class="wp-lightbox"','class="wp-lightbox ws-dialog"');p.write_text(s)
if __name__=='__main__':build()
